_WAY_MARK = re.compile(r'^\[(\w+)\][ \t]*$', re.M)

def join_ways(d:dict) -> str:
    "The text of the prompt `ways` from a dict of way -> text: a section `[way]` for each method."
    return '\n'.join(f'[{m}]\n{d[m]}' for m in METHODS)

def ways_of(text:str) -> dict:
    "The sections of a ways text: way -> its text."
    p = _WAY_MARK.split(text or '')
    return {k: v.strip() for k, v in zip(p[1::2], p[2::2])}

def need_ways(text:str):
    "A check that refuses a ways text that drops, repeats, renames or empties a section, or that has words before the first."
    p = _WAY_MARK.split(text)
    names, body = p[1::2], p[2::2]
    why = [*(f'[{m}] is missing' for m in METHODS if m not in names),
           *(f'[{n}] is not a way' for n in dict.fromkeys(names) if n not in METHODS),
           *(f'[{n}] is there more than once' for n in dict.fromkeys(names) if names.count(n) > 1),
           *(f'[{n}] has no text' for n, b in zip(names, body) if not b.strip()),
           *(['there are words before the first section'] if p[0].strip() else [])]
    if why: raise ValueError(f'The ways text needs one section for each way, and each section starts with a line such as [code] on its own. {"; ".join(why)}.')

WAYS = register('ways', 'Ways to teach', 'How the tutor uses each way in a question, a nudge, a hint and a lesson. Each way has a section that starts with a line such as [code] on its own.', join_ways(METHODS), need_ways)

def way(m:str) -> str:
    "The text of method `m` now: its section of your saved text, else the line in `METHODS`; '' for an unknown method."
    return (ways_of(prompt('ways')).get(m) or METHODS[m]) if m in METHODS else ''

def _carry_ways(ps:dict) -> dict:
    "The saved texts `ps` with each `way.X` moved into the section `X` of `ways`; a saved `ways` stays as it is."
    old = {m: t.strip() for m in METHODS if isinstance(t := ps.get(f'way.{m}'), str) and t.strip()}
    ps = {k: v for k, v in ps.items() if not k.startswith('way.')}
    return {**ps, 'ways': join_ways({**METHODS, **old})} if old and 'ways' not in ps else ps

CARRY.append(_carry_ways)

